import{_ as t,o as r,c as n,a3 as s}from"./chunks/framework.vNrIUzwY.js";const u=JSON.parse('{"title":"Known Issues","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://kilnrender.com/preview/docs-refresh/reference/issues.html"}],["meta",{"property":"og:title","content":"Known Issues | Kiln"}],["meta",{"property":"og:description","content":"A WebGPU renderer that streams large volumetric datasets over HTTP into a bounded VRAM cache."}],["meta",{"property":"og:url","content":"https://kilnrender.com/preview/docs-refresh/reference/issues.html"}],["meta",{"name":"twitter:title","content":"Known Issues | Kiln"}],["meta",{"name":"twitter:description","content":"A WebGPU renderer that streams large volumetric datasets over HTTP into a bounded VRAM cache."}]]},"headers":[],"relativePath":"reference/issues.md","filePath":"reference/issues.md"}'),a={name:"reference/issues.md"};function i(o,e,l,c,d,h){return r(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="known-issues" tabindex="-1">Known Issues <a class="header-anchor" href="#known-issues" aria-label="Permalink to &quot;Known Issues&quot;">​</a></h1><h2 id="rendering" tabindex="-1">Rendering <a class="header-anchor" href="#rendering" aria-label="Permalink to &quot;Rendering&quot;">​</a></h2><ul><li><strong>LOD transitions while streaming.</strong> When finer bricks arrive, the region they cover switches resolution, which can show as a brief discontinuity until the neighbouring bricks catch up.</li><li><strong>Banding while refining.</strong> Temporal accumulation restarts when new bricks are committed, so during heavy refinement the image is built from only a few jittered frames and can show stripes or a woodgrain pattern. It clears once streaming settles and accumulation converges.</li><li><strong>ISO seams at LOD boundaries.</strong> Isosurface normals are central differences whose taps can cross into a neighbouring brick. When that brick is at a different LOD, the normal changes abruptly and the boundary can be faintly visible. DVR gradients stay inside the brick&#39;s ghost border and are not affected.</li><li><strong>Multichannel:</strong> no ISO mode, no transfer function, and DVR is not shaded yet. See <a href="/preview/docs-refresh/rendering/multichannel.html#known-limitations">Multichannel → Known limitations</a>.</li></ul><h2 id="streaming" tabindex="-1">Streaming <a class="header-anchor" href="#streaming" aria-label="Permalink to &quot;Streaming&quot;">​</a></h2><ul><li><strong>OME-Zarr empty bricks are downloaded once.</strong> The sharded binary format stores per-brick statistics, so empty bricks are skipped before any request. OME-Zarr has no such index: a brick is recognised as empty only after it has been assembled, and is skipped from then on.</li><li><strong>The empty threshold is fixed, not learned.</strong> A brick counts as empty when its maximum is below a threshold set by the data type (1 for 8-bit, 100 of 65535 for 16-bit), lowered to the lowest channel window start when there is one. It is not derived from the data&#39;s distribution, so a noisy fluorescence background above that threshold still streams.</li><li><strong>Time series:</strong> one timepoint is loaded at a time; there is no playback or prefetching.</li></ul><h2 id="local-files" tabindex="-1">Local files <a class="header-anchor" href="#local-files" aria-label="Permalink to &quot;Local files&quot;">​</a></h2><ul><li><strong>Sharded Zarr v3 stores can&#39;t be opened from disk.</strong> Reading one chunk out of a shard needs partial reads, which the local file store does not implement yet. Serve such datasets over HTTP instead. See <a href="/preview/docs-refresh/data/local-files.html">Local files</a>.</li></ul>',7)])])}const f=t(a,[["render",i]]);export{u as __pageData,f as default};
